#define LUXE_ORIGINAL_AUTHORS "Principal author:\nAlfredo Kojima <kojima@groovynet.org>\n\nCurrent Maintainer(s):\nMichael Vogt <mvo@debian.org>\nGustavo Niemeyer <niemeyer@conectiva.com>\n\nDebtag support: \nEnrico Zini <enrico@debian.org>\n\nLots of improvements with the glade interface and usability:\nSebastian Heinlein <sebastian.heinlein@web.de>\n\nLots of small fixes/improvements:\nPanu Matilainen <pmatilai@welho.com>"
#include <string.h>
#define LUXE_ABOUT_ICON "luxurystore"
static void luxe_about_credits(GtkAboutDialog *dialog) {
    static const char *contributors[] = {"Jerry Howell (2026)", NULL};
    luxe_about_add_credit_section(dialog, "Luxe development", contributors);
#ifdef LUXE_ORIGINAL_AUTHORS
    static const char *upstream[] = {LUXE_ORIGINAL_AUTHORS, NULL};
    luxe_about_add_credit_section(dialog, "Original authors and contributors", upstream);
#endif
    const char *copyright = gtk_about_dialog_get_copyright(dialog);
    if (!copyright || !g_strstr_len(copyright, -1, "Jerry Howell")) {
        char *updated = g_strconcat(copyright ? copyright : "", "\nCopyright (C) 2026 Jerry Howell", NULL);
        gtk_about_dialog_set_copyright(dialog, updated);
        g_free(updated);
    }
#ifdef LUXE_UPSTREAM_CREDITS
    const char *existing = luxe_about_get_license(dialog);
    char *credits = g_strconcat(existing ? existing : "", "\n\n", LUXE_UPSTREAM_CREDITS, NULL);
    gtk_about_dialog_set_license(dialog, credits);
    g_free(credits);
#endif
}

static void luxe_show_about_full(GtkWindow *parent, const char *name, const char *version, const char *description, const char *translators) {
    GtkWindow *dialog = luxe_about_new();
    g_object_set(dialog,
                 "program-name", name,
                 "logo-icon-name", LUXE_ABOUT_ICON,
                 "version", version,
                 "comments", description,
                 "website", "https://github.com/openconstruct/luxeDE",
                 "copyright", "Copyright (C) 2026 Jerry Howell\nUpstream copyrights and authors: see License",
                 NULL);
    luxe_about_credits(GTK_ABOUT_DIALOG(dialog));
    if (translators && *translators && strcmp(translators, "translator-credits") != 0) {
        gtk_about_dialog_set_translator_credits(GTK_ABOUT_DIALOG(dialog), translators);
    }
    luxe_dialog_present(dialog, GTK_WIDGET(parent));
}

static void luxe_show_about(GtkWindow *parent, const char *name, const char *version, const char *description) {
    luxe_show_about_full(parent, name, version, description, NULL);
}

static void luxe_about_clicked(GtkButton *button, gpointer data) {
    (void)button;
    GtkWindow *window = GTK_WINDOW(data);
    luxe_show_about(window, (const char *)g_object_get_data(G_OBJECT(window), "luxe-about-name"),
        (const char *)g_object_get_data(G_OBJECT(window), "luxe-about-version"),
        (const char *)g_object_get_data(G_OBJECT(window), "luxe-about-description"));
}

static void luxe_add_about_button(GtkWindow *window, const char *name, const char *version, const char *description) {
    GtkWidget *button = gtk_button_new_with_label("About");
    g_object_set_data_full(G_OBJECT(window), "luxe-about-name", g_strdup(name), g_free);
    g_object_set_data_full(G_OBJECT(window), "luxe-about-version", g_strdup(version), g_free);
    g_object_set_data_full(G_OBJECT(window), "luxe-about-description", g_strdup(description), g_free);
    GtkHeaderBar *header = GTK_HEADER_BAR(gtk_window_get_titlebar(window));
    if (!header) {
        header = GTK_HEADER_BAR(gtk_header_bar_new());
        gtk_window_set_titlebar(window, GTK_WIDGET(header));
    }
    gtk_header_bar_pack_end(header, button);
    g_signal_connect(button, "clicked", G_CALLBACK(luxe_about_clicked), window);
}
#endif
